import {initIntro} from './intro.js';

const api='/api',gate=document.querySelector('#auth-gate'),status=gate.querySelector('[data-auth-status]');
const guestButton=gate.querySelector('[data-auth-guest]'),loginForm=gate.querySelector('[data-auth-login]'),signupForm=gate.querySelector('[data-auth-signup]'),googleHost=gate.querySelector('[data-auth-google]');
const copy={
  en:{eyebrow:'YOUR FIELD. YOUR WORKSPACE.',title:'Welcome back.',body:'Log in to continue, or create an account to keep every field decision connected.',google:'Continue with Google',or:'OR',loginTab:'Log in',signupTab:'Create account',usernameLabel:'Username',emailLabel:'Email address',passwordLabel:'Password',loginButton:'Enter FieldShift',signupButton:'Create my account',guest:'Continue as guest',guestNote:'Guest data lasts only for this browser tab and is not saved to an account.',secure:'Passwords are salted and securely hashed. FieldShift never stores the original password.',loading:'Checking your account…',unavailable:'Google sign-in needs a Google Web Client ID. Email and password are ready.',guestChip:'Guest mode',signup:'Sign in',saveCloud:'Cloud-synced workspace',saveCloudBody:'Your fields, journal records and assumptions are saved securely to your account.',saveGuest:'Guest workspace',saveGuestBody:'Your work lasts only in this tab. Sign in to keep it.',signOut:'Sign out'},
  fr:{eyebrow:'VOTRE CHAMP. VOTRE ESPACE.',title:'Bon retour.',body:'Connectez-vous pour continuer ou créez un compte afin de conserver toutes vos décisions agricoles.',google:'Continuer avec Google',or:'OU',loginTab:'Se connecter',signupTab:'Créer un compte',usernameLabel:'Nom d’utilisateur',emailLabel:'Adresse e-mail',passwordLabel:'Mot de passe',loginButton:'Entrer dans FieldShift',signupButton:'Créer mon compte',guest:'Continuer en invité',guestNote:'Les données invité restent uniquement dans cet onglet et ne sont pas enregistrées dans un compte.',secure:'Les mots de passe sont salés et hachés de manière sécurisée. FieldShift ne conserve jamais le mot de passe original.',loading:'Vérification de votre compte…',unavailable:'La connexion Google nécessite un identifiant client Web Google. E-mail et mot de passe sont prêts.',guestChip:'Mode invité',signup:'Se connecter',saveCloud:'Espace synchronisé dans le cloud',saveCloudBody:'Vos champs, journaux et hypothèses sont enregistrés en toute sécurité dans votre compte.',saveGuest:'Espace invité',saveGuestBody:'Votre travail reste dans cet onglet. Connectez-vous pour le conserver.',signOut:'Se déconnecter'},
  ar:{eyebrow:'حقلك. مساحة عملك.',title:'مرحباً بعودتك.',body:'سجّل الدخول للمتابعة أو أنشئ حساباً للاحتفاظ بجميع قرارات حقلك.',google:'المتابعة باستخدام Google',or:'أو',loginTab:'تسجيل الدخول',signupTab:'إنشاء حساب',usernameLabel:'اسم المستخدم',emailLabel:'البريد الإلكتروني',passwordLabel:'كلمة المرور',loginButton:'دخول FieldShift',signupButton:'إنشاء حسابي',guest:'المتابعة كضيف',guestNote:'تدوم بيانات الضيف في علامة التبويب هذه فقط ولا تُحفظ في حساب.',secure:'تُملّح كلمات المرور وتُجزّأ بأمان. لا يخزن FieldShift كلمة المرور الأصلية.',loading:'جارٍ التحقق من حسابك…',unavailable:'يحتاج تسجيل Google إلى معرّف عميل ويب من Google. البريد وكلمة المرور جاهزان.',guestChip:'وضع الضيف',signup:'تسجيل الدخول',saveCloud:'مساحة عمل متزامنة سحابياً',saveCloudBody:'تُحفظ حقولك وسجلاتك وافتراضاتك بأمان في حسابك.',saveGuest:'مساحة عمل الضيف',saveGuestBody:'يبقى عملك في علامة التبويب هذه. سجّل الدخول للاحتفاظ به.',signOut:'تسجيل الخروج'}
};
function language(){for(const store of [sessionStorage,localStorage])try{const value=JSON.parse(store.getItem('fieldshift.preferences'));if(copy[value?.language])return value.language;}catch{}return copy[navigator.language?.slice(0,2)]?navigator.language.slice(0,2):'en';}
const words=copy[language()];for(const [key,value] of Object.entries(words))gate.querySelectorAll(`[data-copy="${key}"]`).forEach(el=>el.textContent=value);
let started=false,syncTimer;
const fieldKeys=store=>Object.keys(store).filter(key=>key.startsWith('fieldshift.')&&!key.includes('intro.skip-auto'));
const snapshot=store=>Object.fromEntries(fieldKeys(store).map(key=>[key,store.getItem(key)]));
function accountStorage(){return{getItem:key=>localStorage.getItem(key),setItem(key,value){localStorage.setItem(key,value);scheduleSync();},removeItem(key){localStorage.removeItem(key);scheduleSync();}};}
async function sync(){const response=await fetch(api+'/workspace',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({data:snapshot(localStorage)})});if(!response.ok)throw new Error('Workspace sync failed');window.dispatchEvent(new CustomEvent('fieldshift:sync',{detail:{state:'saved'}}));}
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync().catch(()=>window.dispatchEvent(new CustomEvent('fieldshift:sync',{detail:{state:'error'}}))),700);}
async function start(mode,user){if(started)return;started=true;window.__fieldshiftAccount=user||null;window.__fieldshiftStorage=mode==='guest'?sessionStorage:accountStorage();gate.classList.add('leaving');setTimeout(()=>gate.hidden=true,360);await import('./app.js');addAccountControl(mode,user);}
function addAccountControl(mode,user){const top=document.querySelector('.topbar-right');if(!top)return;const control=document.createElement('button');control.className='auth-chip';control.type='button';if(mode==='account'){control.title=words.signOut;control.innerHTML=`<span></span><b>${escapeHTML(user.username||user.name||user.email)}</b><small>${words.signOut}</small>`;control.onclick=async()=>{await fetch(api+'/auth/logout',{method:'POST'});location.reload();};}else{control.innerHTML=`<span></span><b>${words.guestChip}</b><small>${words.signup}</small>`;control.onclick=()=>{gate.hidden=false;gate.classList.remove('leaving');requestAnimationFrame(()=>gate.classList.add('visible','ready'));};}top.prepend(control);const setting=[...document.querySelectorAll('.setting-item')].find(item=>item.querySelector('b')?.textContent.includes('Device-local'));if(setting){setting.querySelector('b').textContent=mode==='account'?words.saveCloud:words.saveGuest;setting.querySelector('p').textContent=mode==='account'?words.saveCloudBody:words.saveGuestBody;setting.querySelector('.pill').textContent=mode==='account'?'SYNCED':'SESSION';}}
const escapeHTML=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function setBusy(form,busy){form.querySelectorAll('input,button').forEach(el=>el.disabled=busy);}
function activateTab(name){gate.querySelectorAll('[data-auth-tab]').forEach(button=>{const active=button.dataset.authTab===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));});loginForm.hidden=name!=='login';signupForm.hidden=name!=='signup';status.textContent='';(name==='login'?loginForm:signupForm).querySelector('input').focus();}
gate.querySelectorAll('[data-auth-tab]').forEach(button=>button.onclick=()=>activateTab(button.dataset.authTab));
guestButton.onclick=()=>{sessionStorage.setItem('fieldshift.guest','1');start('guest');};
async function submitPassword(form,endpoint){const values=Object.fromEntries(new FormData(form));setBusy(form,true);status.textContent='';try{const response=await fetch(api+endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Unable to continue.');await loadAccount(data.user);}catch(error){status.textContent=error.message;}finally{setBusy(form,false);}}
loginForm.onsubmit=event=>{event.preventDefault();submitPassword(loginForm,'/auth/login');};
signupForm.onsubmit=event=>{event.preventDefault();submitPassword(signupForm,'/auth/signup');};
async function googleCredential(response){status.textContent=words.loading;try{const result=await fetch(api+'/auth/google',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({credential:response.credential})});const data=await result.json();if(!result.ok)throw new Error(data.error||words.unavailable);await loadAccount(data.user);}catch(error){status.textContent=error.message;}}
async function configureGoogle(){try{const response=await fetch(api+'/auth/config');const config=await response.json();if(config.googleClientId){await loadGoogle();google.accounts.id.initialize({client_id:config.googleClientId,callback:googleCredential});googleHost.innerHTML='';google.accounts.id.renderButton(googleHost,{theme:'outline',size:'large',shape:'rectangular',width:400,text:'continue_with'});}else{googleHost.querySelector('button').disabled=true;status.textContent=words.unavailable;}}catch{status.textContent=words.unavailable;}}
function loadGoogle(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.id)return resolve();const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=reject;document.head.append(script);});}
async function loadAccount(identity){const saved=await fetch(api+'/workspace');const payload=saved.ok?await saved.json():{data:{}};const cloud=payload.data||{},guest=snapshot(sessionStorage),merged=Object.keys(cloud).length?cloud:{...snapshot(localStorage),...guest};fieldKeys(localStorage).forEach(key=>localStorage.removeItem(key));for(const [key,value] of Object.entries(merged))if(key.startsWith('fieldshift.')&&typeof value==='string')localStorage.setItem(key,value);await start('account',identity);if(!Object.keys(cloud).length&&Object.keys(merged).length)scheduleSync();}
async function boot(){status.textContent=words.loading;if(location.protocol==='file:'||((location.hostname==='127.0.0.1'||location.hostname==='localhost')&&!new URLSearchParams(location.search).has('auth-preview'))){await start('guest');return;}try{const response=await fetch(api+'/me');if(!response.ok)throw new Error();const identity=await response.json();if(identity.authenticated){await loadAccount(identity);return;}gate.classList.add('visible','ready');status.textContent='';await configureGoogle();}catch{gate.classList.add('visible','ready');status.textContent=words.unavailable;}}
function begin(){if(sessionStorage.getItem('fieldshift.intro.skip-auto'))boot();else{gate.classList.remove('visible');window.addEventListener('fieldshift:intro:closed',boot,{once:true});window.__fieldshiftIntro=initIntro({language:language()});}}
begin();
